"""Checks actual files generated by reverse_engineer.py, not mocks."""
import json
from pathlib import Path
import unittest
ROOT=Path(__file__).resolve().parents[1]
class ReconstructionTests(unittest.TestCase):
    def setUp(self):
        p=ROOT/'reports/reconstruction/edit_plan.json'
        if not p.exists():self.skipTest('Run reverse_engineer.py to create real artifacts')
        self.plan=json.loads(p.read_text())
    def test_complete_coverage(self):
        blocks=self.plan['blocks'];self.assertEqual(blocks[0]['start_frame'],0)
        self.assertEqual(blocks[-1]['end_frame_exclusive'],1246)
        for a,b in zip(blocks,blocks[1:]):self.assertEqual(a['end_frame_exclusive'],b['start_frame'])
    def test_frame_count(self):self.assertTrue(self.plan['result']['frame_count_matches'])
    def test_decode(self):self.assertTrue(self.plan['result']['full_decode_passed'])
    def test_no_false_recovery_claim(self):
        self.assertEqual(self.plan['recovery']['speed_ramp_curves'],'not recovered')
        self.assertEqual(self.plan['recovery']['zoom_curves'],'not recovered')
    def test_no_fake_bpm(self):
        a=json.loads((ROOT/'reports/reconstruction/audio_energy.json').read_text());self.assertIsNone(a['bpm']);self.assertFalse(a['beats_verified'])
    def test_real_artifacts(self):
        for name in ['reconstructed_timeline.mp4','reconstruction_breakdown.mp4']:
            self.assertGreater((ROOT/'outputs'/name).stat().st_size,100000)
